"""Lexer boundary for jq source text.

The lexer intentionally owns source positions and invalid-character detection;
the parser never needs to inspect raw source characters.
"""

from dataclasses import dataclass

from .ast import SourceLocation
from .errors import CompileError


@dataclass(frozen=True)
class Token:
    kind: str
    value: str
    location: SourceLocation


def tokenize(source: str) -> list[Token]:
    """Tokenize the foundation's shared punctuation and JSON atoms."""

    tokens: list[Token] = []
    index = 0
    line = 1
    column = 1
    punctuation = {"|": "PIPE", ",": "COMMA", ".": "DOT", "(": "LPAREN", ")": "RPAREN"}
    while index < len(source):
        char = source[index]
        if char.isspace():
            if char == "\n":
                line, column = line + 1, 1
            else:
                column += 1
            index += 1
            continue
        location = SourceLocation(line, column)
        if char in punctuation:
            tokens.append(Token(punctuation[char], char, location))
            index += 1
            column += 1
            continue
        if char == '"':
            end = index + 1
            escaped = False
            while end < len(source):
                current = source[end]
                if current == '"' and not escaped:
                    break
                escaped = current == "\\" and not escaped
                if current != "\\":
                    escaped = False
                end += 1
            if end == len(source):
                raise CompileError("unterminated string")
            tokens.append(Token("STRING", source[index : end + 1], location))
            width = end + 1 - index
            index, column = end + 1, column + width
            continue
        if char.isdigit() or char == "-":
            end = index + 1
            while end < len(source) and source[end] in "0123456789.eE+-":
                end += 1
            tokens.append(Token("NUMBER", source[index:end], location))
            column += end - index
            index = end
            continue
        if source.startswith("true", index) or source.startswith("false", index) or source.startswith("null", index):
            end = index + (4 if source.startswith("true", index) else 5 if source.startswith("false", index) else 4)
            tokens.append(Token("ATOM", source[index:end], location))
            column += end - index
            index = end
            continue
        raise CompileError(f"invalid character at {line}:{column}")
    tokens.append(Token("EOF", "", SourceLocation(line, column)))
    return tokens
